<div class="header flexbox" data-base-validator >
  <div class="header-left flexbox align-items-center">
      <a href="javascript:void(0)" class="toggle-menu">
        <svg viewBox="0 0 22 15" version="1.1" x="0px" y="0px" width="22px" height="15px">
          <g>
            <path d="M 0.9998 8.1758 L 0.9998 5.842 L 21.9999 5.842 L 21.9999 8.1758 L 0.9998 8.1758 ZM 0.9998 0.0069 L 17.5554 0.0069 L 17.5554 2.3409 L 0.9998 2.3409 L 0.9998 0.0069 ZM 13.6665 14.0109 L 0.9998 14.0109 L 0.9998 11.6769 L 13.6665 11.6769 L 13.6665 14.0109 Z"/>
          </g>
        </svg>
      </a>

      <a href="{{url('admin/dashboard')}}" class="logo_panel">
        <img src="{{asset('assets/images').'/'.config( 'settings.general-settings.site-settings.logo' )}}">
      </a>
  </div>

  <div class="header-uploading-status" id="header-progress"  style="display:none">
     <div class="flexbox align-items-center">
        <div data-ng-repeat="video in videoDetails" ng-if="progress_index == $index" class="flexbox align-items-center">
          <span class="transc-count">(@{{ progress_index+1 }}/@{{ videoCount }})</span>
          <h4 class="transc-title"><span class="transc-video-name">@{{ video.title }}</span> <span>is Transcoding @{{ video.upload_percentage }}%</span></h4>
        </div>
        <div class="trans-navigation" ng-if="videoCount > 1">
          <svg width="12px" height="8px" viewBox="0 0 25.2 17.779" class="prev-arrow" ng-class="((progress_index == videoCount) || (progress_index == 0)) ? 'disabled' : 'active'" ng-click="previous()">           
            <path class="prev" d="M8.165,4.938a.886.886,0,0,1,1.26,1.247L3.037,12.574H24.118a.878.878,0,0,1,.882.883.887.887,0,0,1-.882.895H3.037l6.389,6.377a.9.9,0,0,1,0,1.26.883.883,0,0,1-1.26,0l-7.9-7.9a.868.868,0,0,1,0-1.247Z" stroke-width="0.2px" transform="translate(0.1 -4.574)"></path>
          </svg>
          <svg width="12px" height="8px" viewBox="0 0 25.2 17.779" class="next-arrow" ng-class="(progress_index != videoCount-1) ? 'active' : 'disabled'" ng-click="next()">            
          <path class="next" d="M16.835,4.938a.886.886,0,0,0-1.26,1.247l6.389,6.389H.882A.878.878,0,0,0,0,13.457a.887.887,0,0,0,.882.895H21.963l-6.389,6.377a.9.9,0,0,0,0,1.26.883.883,0,0,0,1.26,0l7.9-7.9a.868.868,0,0,0,0-1.247Z" stroke="#747474" stroke-width="0.2px" transform="translate(0.1 -4.574)"></path>
          </svg>
        </div>
      </div>
      <div style="display:none;">
        <div class="flexbox align-items-center">          
            <svg viewBox="0 0 129 129" width="12px" height="12px" ng-click="previous()" class="prev-arrow">
              <g>
                <path d="m88.6,121.3c0.8,0.8 1.8,1.2 2.9,1.2s2.1-0.4 2.9-1.2c1.6-1.6 1.6-4.2 0-5.8l-51-51 51-51c1.6-1.6 1.6-4.2 0-5.8s-4.2-1.6-5.8,0l-54,53.9c-1.6,1.6-1.6,4.2 0,5.8l54,53.9z" fill="#747474"/>
              </g>
            </svg>
          <div  data-ng-repeat="video in videoDetails" ng-if="progress_index == $index">
            <h3>(@{{ progress_index+1 }}/@{{ videoCount }}) {{ __('base::general.header_progress_bar_content') }}...</h3>
              <div class="status flexbox align-items-center">
                <a  href="{{url('admin/videos')}}"
                class="table-image-text flexbox align-items-center">
                @{{ video.title }}</a>
                <div class="upload-progress">
                  <span style="width: @{{ video.upload_percentage }}%"></span>
                </div>
                <span class="count">@{{ video.upload_percentage }}% </span>
              </div>
          </div>
            <svg class="next-arrow" ng-click="next()" viewBox="0 0 129 129" width="12px" height="12px">
              <g>
                <path d="m40.4,121.3c-0.8,0.8-1.8,1.2-2.9,1.2s-2.1-0.4-2.9-1.2c-1.6-1.6-1.6-4.2 0-5.8l51-51-51-51c-1.6-1.6-1.6-4.2 0-5.8 1.6-1.6 4.2-1.6 5.8,0l53.9,53.9c1.6,1.6 1.6,4.2 0,5.8l-53.9,53.9z" fill="#747474"/>
              </g>
            </svg>
        </div>       
      </div>
  </div>

